#:sdk Microsoft.NET.Sdk.Web #:package ZoneTree@1.4.0 #:property LangVersion=preview #:property TargetFramework=net10.0 #:property Nullable=enable #:property ImplicitUsings=enable  using System.Collections.Concurrent; using ZoneTree.Core; using ZoneTree.Options;  public class TreeNode {     public int Id { get; set; }     public string Name { get; set; }     public int? ParentId { get; set; }     public List<int> ChildrenIds { get; set; } = new();     public int Order { get; set; } // 新增排序字段     public DateTime ModifiedTime { get; set; } // 记录修改时间 }  public interface ITreeService {     Task<TreeNode> GetNodeAsync(int id);     Task AddNodeAsync(TreeNode node);     Task UpdateNodeAsync(TreeNode node);     Task DeleteNodeAsync(int id);     Task<IEnumerable<TreeNode>> GetDescendantsAsync(int parentId);     Task ReorderChildrenAsync(int parentId, IEnumerable<int> newOrderIds);     Task RedoNodeAsync(int id); }  public class TreeService : ITreeService {     private readonly IZoneTree<int, TreeNode> _zoneTree;     private readonly ConcurrentDictionary<int, ReaderWriterLockSlim> _nodeLocks;     private readonly ConcurrentDictionary<int, Stack<TreeNode>> _undoStacks = new();          public TreeService()     {         var options = new ZoneTreeOptions<int, TreeNode>         {             // 配置ZoneTree参数             WriteAheadLogOptions = new WriteAheadLogOptions             {                 WriteAheadLogMode = WriteAheadLogMode.Sync,                 SegmentSize = 1024 * 1024 * 100 // 100MB             },             MutableSegmentMaxItemCount = 1_000_000,             DiskSegmentMode = DiskSegmentMode.SingleDiskSegment         };                  _zoneTree = new ZoneTreeFactory<int, TreeNode>()             .SetOptions(options)             .OpenOrCreate();                      _nodeLocks = new ConcurrentDictionary<int, ReaderWriterLockSlim>();     }         // 新增内存缓存优化     private readonly MemoryCache<int, TreeNode> _nodeCache = new(new MemoryCacheOptions     {         SizeLimit = 10_000     });          // 新增索引结构     private readonly ConcurrentDictionary<string, List<int>> _nameIndex = new();     private readonly ConcurrentDictionary<int, int> _parentIndex = new();          // 持久化节点     private async Task PersistNodeAsync(TreeNode node)     {         var lockObj = _nodeLocks.GetOrAdd(node.Id, _ => new ReaderWriterLockSlim());         lockObj.EnterWriteLock();         try         {             // 写入ZoneTree             _zoneTree.Upsert(node.Id, node);                          // 更新内存缓存             _nodeCache.Set(node.Id, node, new MemoryCacheEntryOptions             {                 Size = 1,                 SlidingExpiration = TimeSpan.FromMinutes(30)             });                          // 更新名称索引             var nameKey = node.Name.ToLowerInvariant();             _nameIndex.AddOrUpdate(nameKey,                  _ => new HashSet<int> { node.Id },                 (_, set) => { set.Add(node.Id); return set; });                          // 更新父节点索引             if (node.ParentId.HasValue)             {                 _parentIndex.AddOrUpdate(node.Id, node.ParentId.Value, (_, __) => node.ParentId.Value);             }         }         finally         {             lockObj.ExitWriteLock();         }     }          // 模糊查找     public async Task<IEnumerable<TreeNode>> FuzzySearchAsync(string keyword)     {         var result = new List<TreeNode>();         var keywordLower = keyword.ToLowerInvariant();                  // 并行搜索所有包含关键字的节点         var matchedKeys = _nameIndex.Keys             .AsParallel()             .Where(k => k.Contains(keywordLower))             .SelectMany(k => _nameIndex[k]);                      foreach (var id in matchedKeys)         {             var node = await GetNodeAsync(id);             if (node != null) result.Add(node);         }                  return result;     }          // 获取父节点     public async Task<TreeNode> GetParentAsync(int nodeId)     {         using (await _rwLock.ReaderLockAsync())         {             return _parentIndex.TryGetValue(nodeId, out var parentId) &&                     _zoneTree.TryGet(parentId, out var parentNode)                 ? parentNode                 : null;         }     }          // 获取所有子节点     public async Task<IEnumerable<TreeNode>> GetChildrenAsync(int parentId)     {         var result = new List<TreeNode>();         foreach (var child in _zoneTree.Where(x => x.Value.ParentId == parentId))         {             result.Add(child.Value);         }         return result;     }          // 获取节点时优先从缓存读取     public async Task<TreeNode> GetNodeAsync(int id)     {         if (_nodeCache.TryGetValue(id, out var cachedNode))             return cachedNode;                      var lockObj = _nodeLocks.GetOrAdd(id, _ => new ReaderWriterLockSlim());         lockObj.EnterReadLock();         try         {             var node = _zoneTree.Get(id);             if (node != null)             {                 _nodeCache.Set(id, node, new MemoryCacheEntryOptions                 {                     Size = 1,                     SlidingExpiration = TimeSpan.FromMinutes(30)                 });             }             return node;         }         finally         {             lockObj.ExitReadLock();         }     }          // 批量加载节点到缓存     public async Task WarmUpCacheAsync(IEnumerable<int> ids)     {         await Parallel.ForEachAsync(ids, async (id, ct) =>          {             await GetNodeAsync(id);         });     }      public async Task AddNodeAsync(TreeNode node)     {         var lockObj = _nodeLocks.GetOrAdd(node.Id, _ => new ReaderWriterLockSlim());         lockObj.EnterWriteLock();         try         {             if (node.ParentId.HasValue)             {                 var parentLock = _nodeLocks.GetOrAdd(node.ParentId.Value, _ => new ReaderWriterLockSlim());                 parentLock.EnterWriteLock();                 try                 {                     var parent = _zoneTree.Get(node.ParentId.Value);                     parent.ChildrenIds.Add(node.Id);                     _zoneTree.Upsert(parent.Id, parent);                 }                 finally                 {                     parentLock.ExitWriteLock();                 }             }             _zoneTree.Upsert(node.Id, node);         }         finally         {             lockObj.ExitWriteLock();         }     }      public async Task UpdateNodeAsync(TreeNode node)     {         var lockObj = _nodeLocks.GetOrAdd(node.Id, _ => new ReaderWriterLockSlim());         lockObj.EnterWriteLock();         try         {             _zoneTree.Upsert(node.Id, node);         }         finally         {             lockObj.ExitWriteLock();         }     }      public async Task DeleteNodeAsync(int id)     {         var lockObj = _nodeLocks.GetOrAdd(id, _ => new ReaderWriterLockSlim());         lockObj.EnterWriteLock();         try         {             var node = _zoneTree.Get(id);             if (node.ParentId.HasValue)             {                 var parentLock = _nodeLocks.GetOrAdd(node.ParentId.Value, _ => new ReaderWriterLockSlim());                 parentLock.EnterWriteLock();                 try                 {                     var parent = _zoneTree.Get(node.ParentId.Value);                     parent.ChildrenIds.Remove(id);                     _zoneTree.Upsert(parent.Id, parent);                 }                 finally                 {                     parentLock.ExitWriteLock();                 }             }                          // 递归删除所有子节点             foreach (var childId in node.ChildrenIds)             {                 await DeleteNodeAsync(childId);             }                          _zoneTree.Delete(id);             _nodeLocks.TryRemove(id, out _);         }         finally         {             lockObj.ExitWriteLock();         }     }      public async Task<IEnumerable<TreeNode>> GetDescendantsAsync(int nodeId)     {         using (await _rwLock.ReaderLockAsync())         {             var result = new List<TreeNode>();             var queue = new Queue<int>();             queue.Enqueue(nodeId);                  while (queue.Count > 0)             {                 var currentId = queue.Dequeue();                 if (_zoneTree.TryGet(currentId, out var currentNode))                 {                     result.Add(currentNode);                     foreach (var childId in currentNode.ChildrenIds)                     {                         queue.Enqueue(childId);                     }                 }             }             return result;         }     }      // 新增方法     public async Task<IEnumerable<TreeNode>> GetSiblingsAsync(int id)     {         var node = await GetNodeAsync(id);         if (node?.ParentId == null) return Enumerable.Empty<TreeNode>();                  var parent = await GetNodeAsync(node.ParentId.Value);         return parent?.ChildrenIds             .Where(x => x != id)             .Select(x => _zoneTree.Get(x))             .Where(x => x != null);     }      public async Task MoveNodeAsync(int nodeId, int? newParentId)     {         var node = await GetNodeAsync(nodeId);         if (node == null) return;          // 从原父节点移除         if (node.ParentId.HasValue)         {             var oldParentLock = _nodeLocks.GetOrAdd(node.ParentId.Value, _ => new ReaderWriterLockSlim());             oldParentLock.EnterWriteLock();             try             {                 var oldParent = _zoneTree.Get(node.ParentId.Value);                 oldParent.ChildrenIds.Remove(nodeId);                 _zoneTree.Upsert(oldParent.Id, oldParent);             }             finally             {                 oldParentLock.ExitWriteLock();             }         }          // 添加到新父节点         if (newParentId.HasValue)         {             var newParentLock = _nodeLocks.GetOrAdd(newParentId.Value, _ => new ReaderWriterLockSlim());             newParentLock.EnterWriteLock();             try             {                 var newParent = _zoneTree.Get(newParentId.Value);                 newParent.ChildrenIds.Add(nodeId);                 _zoneTree.Upsert(newParent.Id, newParent);             }             finally             {                 newParentLock.ExitWriteLock();             }         }          // 更新节点         node.ParentId = newParentId;         await UpdateNodeAsync(node);     }          public async Task ReorderChildrenAsync(int parentId, IEnumerable<int> newOrderIds)     {         var parentLock = _nodeLocks.GetOrAdd(parentId, _ => new ReaderWriterLockSlim());         parentLock.EnterWriteLock();         try         {             var parent = await GetNodeAsync(parentId);             if (parent == null) return;                          // 验证所有子节点ID是否有效             var children = parent.ChildrenIds.ToHashSet();             if (!newOrderIds.All(id => children.Contains(id)))                 throw new ArgumentException("包含无效的子节点ID");                          // 更新排序顺序             var orderedChildren = newOrderIds.ToList();             parent.ChildrenIds = orderedChildren;                          // 更新子节点的Order属性             for (int i = 0; i < orderedChildren.Count; i++)             {                 var childId = orderedChildren[i];                 var childLock = _nodeLocks.GetOrAdd(childId, _ => new ReaderWriterLockSlim());                 childLock.EnterWriteLock();                 try                 {                     var child = await GetNodeAsync(childId);                     if (child != null)                     {                         child.Order = i;                         child.ModifiedTime = DateTime.UtcNow;                         await PersistNodeAsync(child);                     }                 }                 finally                 {                     childLock.ExitWriteLock();                 }             }                          await PersistNodeAsync(parent);         }         finally         {             parentLock.ExitWriteLock();         }     }          public async Task RedoNodeAsync(int id)     {         var lockObj = _nodeLocks.GetOrAdd(id, _ => new ReaderWriterLockSlim());         lockObj.EnterWriteLock();         try         {             if (!_undoStacks.TryGetValue(id, out var stack) || stack.Count == 0)                 return;                          var previousState = stack.Pop();             var currentNode = await GetNodeAsync(id);                          // 保存当前状态到重做栈             if (currentNode != null)             {                 if (!_undoStacks.TryGetValue(id, out var redoStack))                 {                     redoStack = new Stack<TreeNode>();                     _undoStacks[id] = redoStack;                 }                 redoStack.Push(currentNode.Clone());             }                          // 恢复之前的状态             if (previousState != null)             {                 await PersistNodeAsync(previousState);             }         }         finally         {             lockObj.ExitWriteLock();         }     }          // 修改UpdateNodeAsync方法以支持撤销     public async Task UpdateNodeAsync(TreeNode node)     {         var lockObj = _nodeLocks.GetOrAdd(node.Id, _ => new ReaderWriterLockSlim());         lockObj.EnterWriteLock();         try         {             var existingNode = await GetNodeAsync(node.Id);             if (existingNode != null)             {                 // 保存当前状态到撤销栈                 if (!_undoStacks.TryGetValue(node.Id, out var stack))                 {                     stack = new Stack<TreeNode>();                     _undoStacks[node.Id] = stack;                 }                 stack.Push(existingNode.Clone());             }                          node.ModifiedTime = DateTime.UtcNow;             await PersistNodeAsync(node);         }         finally         {             lockObj.ExitWriteLock();         }     } }  // DI扩展方法 public static class TreeServiceExtensions {     public static IServiceCollection AddTreeServices(this IServiceCollection services)     {